export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = undefined
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Add threshold validation results if thresholds are provided
  if (thresholds && typeof thresholds === 'object' && Object.keys(thresholds).length > 0) {
    // Convert thresholds object to array format for validation and evaluation
    const thresholdArray = Object.entries(thresholds).map(([metric, min]) => ({
      metric,
      min
    }));

    // Validate thresholds
    const validationResult = validateThresholds(
      thresholdArray.map((t) => `${t.metric}=${t.min}`),
      evaluations
    );

    if (validationResult.valid) {
      // Evaluate thresholds
      const thresholdResults = evaluateThresholds(validationResult.thresholds, evaluations);
      report.passed = computeOverallPass(thresholdResults);
      report.thresholds = thresholdResults;
    }
    // If validation fails, we still include the passed and thresholds fields
    // with an error indicator (this is for SDK users to handle gracefully)
  }

  return report;
}

