function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Validate thresholds if provided
  let thresholdsObject: Record<string, number> | undefined;
  if (options.threshold && options.threshold.length > 0) {
    // Import threshold parser dynamically since frai-core is CommonJS
    const validateThresholds = require('frai-core/dist/eval/threshold-validator').validateThresholds;

    const validationResult = validateThresholds(options.threshold, evaluations);
    if (!validationResult.valid) {
      log.error('Invalid threshold options:');
      validationResult.errors.forEach((err: string) => {
        console.error(`  ${err}`);
      });
      process.exit(2);
    }

    // Convert validated thresholds array to object for SDK
    thresholdsObject = {};
    for (const threshold of validationResult.thresholds) {
      thresholdsObject[threshold.metric] = threshold.min;
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholdsObject
  });

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Handle threshold pass/fail for exit codes
  if (report.passed === false) {
    process.exit(1);
  }
}

